function splitSyllables(word){
 // Same reading-unit convention as the user's «Слова по слогам» generator.
 // One vowel per unit. In a consonant cluster, move the last letter to the
 // next unit; a final ь/ъ stays with the preceding unit (ночь·ю, семь·я).
 // This deliberately does not apply line-break/hyphenation restrictions.
 const chars=[...word],vowels='аеёиоуыэюяАЕЁИОУЫЭЮЯ',signs='ьЬъЪ';
 const parts=[];let current=[];
 const isVowel=ch=>vowels.includes(ch);
 for(const ch of chars){
  if(isVowel(ch)&&current.some(isVowel)){
   let last=current.length-1;
   while(last>=0&&!isVowel(current[last]))last--;
   const consonants=current.slice(last+1);
   if(consonants.length===0||signs.includes(consonants[consonants.length-1])){
    parts.push(current.join(''));current=[ch];
   }else{
    parts.push(current.slice(0,-1).join(''));
    current=[consonants[consonants.length-1],ch];
   }
  }else current.push(ch);
 }
 if(current.length)parts.push(current.join(''));
 return parts.join('·');
}


