function illustration(pic,word,interactive=true){
 const cell=illustrationMap[pic];
 const src=cell.src||'illustrations/sheet-'+cell.sheet+'.png';
 const wrapper=document.createElement('span');
 wrapper.className=interactive?'pic illustrated':'dictionary-pic illustrated';
 wrapper.title=displayText(word);
 if(interactive){wrapper.tabIndex=0;wrapper.setAttribute('role','button');wrapper.setAttribute('aria-label','Подсказка: '+displayText(word));}
 else{wrapper.setAttribute('role','img');wrapper.setAttribute('aria-label',displayText(word));}
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
 svg.setAttribute('viewBox',`${cell.x} ${cell.y} ${cell.width} ${cell.height}`);
 svg.setAttribute('preserveAspectRatio','xMidYMid meet');
 svg.setAttribute('aria-hidden','true');
 const image=document.createElementNS('http://www.w3.org/2000/svg','image');
 image.setAttribute('href',src);
 image.setAttribute('width',String(cell.imageWidth||1122));image.setAttribute('height',String(cell.imageHeight||1402));
 svg.append(image);
 // The regular image also lets the print action await image decoding.
 const img=document.createElement('img');img.className='illustration-preload';
 img.src=src;img.alt='';img.draggable=false;
 wrapper.append(svg,img);return wrapper;
}


